// Workflow status API — the live readout DR-0061 Stage 2 needs: which n8n
// workflows exist, which are active, and how the last run went. Read-only.
//
// Setup on the NAS (one time):
//   1. n8n -> Settings -> n8n API -> create an API key.
//   2. Save it: echo -n "<API_KEY>" > /data/secrets/n8n-api-key.txt
//   3. The webhook bearer already exists at /data/secrets/n8n-webhook-bearer.txt
//      (same secret the PWA sends). Import this workflow and ACTIVATE it.
// Until step 2 is done the endpoint returns { ok:false, error:'...' } so the
// app shows a clear "connect the feed" state instead of fake data.

const fs = require('fs');

const API_BASE = 'http://localhost:5678/api/v1';
const BEARER_FILE = '/data/secrets/n8n-webhook-bearer.txt';
const APIKEY_FILE = '/data/secrets/n8n-api-key.txt';
const EXEC_LIMIT = 100;

function readSecret(p) {
  try { return fs.readFileSync(p, 'utf8').trim(); } catch (e) { return ''; }
}

const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};

// Bearer gate (defense in depth; the NAS being LAN/Funnel-only is the real
// boundary). Accept Authorization: Bearer <secret> matching the shared file.
const expected = readSecret(BEARER_FILE);
const auth = String(headers.authorization || headers.Authorization || '');
const presented = auth.replace(/^Bearer\s+/i, '').trim();
if (expected && presented !== expected) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}

const apiKey = readSecret(APIKEY_FILE);
if (!apiKey) {
  return [{ json: { ok: false, error: 'n8n API key not configured at /data/secrets/n8n-api-key.txt' } }];
}

const apiHeaders = { 'X-N8N-API-KEY': apiKey, 'Accept': 'application/json' };

async function getJson(url) {
  const r = await fetch(url, { headers: apiHeaders, signal: AbortSignal.timeout(8000) });
  if (!r.ok) throw new Error('API ' + r.status + ' for ' + url);
  return await r.json();
}

let workflows, executions;
try {
  const wfResp = await getJson(API_BASE + '/workflows?limit=250');
  workflows = Array.isArray(wfResp.data) ? wfResp.data : [];
  const exResp = await getJson(API_BASE + '/executions?limit=' + EXEC_LIMIT + '&includeData=false');
  executions = Array.isArray(exResp.data) ? exResp.data : [];
} catch (e) {
  return [{ json: { ok: false, error: 'n8n API read failed: ' + String(e && e.message || e) } }];
}

// Map workflowId -> most recent execution outcome.
const lastByWf = {};
for (const ex of executions) {
  const wfId = String(ex.workflowId || (ex.workflowData && ex.workflowData.id) || '');
  if (!wfId) continue;
  const when = ex.stoppedAt || ex.startedAt || ex.createdAt || null;
  // status field varies by n8n version; fall back to finished boolean.
  let status = ex.status || (ex.finished === true ? 'success' : (ex.finished === false ? 'error' : 'unknown'));
  status = String(status).toLowerCase();
  const prev = lastByWf[wfId];
  if (!prev || (when && prev.when && when > prev.when) || (when && !prev.when)) {
    lastByWf[wfId] = { when, status };
  }
}

const out = workflows.map(w => {
  const last = lastByWf[String(w.id)] || null;
  return {
    name: w.name || '(unnamed)',
    active: w.active === true,
    last_run: last ? last.when : null,
    last_status: last ? last.status : 'never-run',
  };
}).sort((a, b) => Number(b.active) - Number(a.active) || a.name.localeCompare(b.name));

const activeCount = out.filter(w => w.active).length;
const recentErrors = Object.values(lastByWf).filter(l => l.status === 'error' || l.status === 'crashed').length;

return [{ json: { ok: true, generated_at: new Date().toISOString(), total: out.length, active: activeCount, recent_errors: recentErrors, workflows: out } }];
